#!/usr/bin/env bash
# Integration of the behaviours of the examples rve (ex6,
# SaintVenantKirchhoffElasticity) and ssna303_3d (ex4,
# IsotropicLinearHardeningPlasticity with the logarithmic strain) on one
# point, on the AMD GPU gfx1036, the libraries being generated by MFront
# (generic-parallel interface, hip backend) and compiled by the hipcc of ROCm
# at each optimisation level given by LEVELS (O1 O2 by default), in plane
# strain and in 3D. A run blocked more than 30 s is killed.
#
# usage: [LEVELS="O1 O2 O3"] [ARCH=gfx1036] reproducers/hip-finite-strain-3d-hang/run.sh
# (through `sg render` if the session does not have the group render yet)
set -euo pipefail

R=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$R/../.." && pwd)
ROCM_VENV=${ROCM_VENV:-$HOME/Bureau/rocm-sdk-therock/venv}
ROCM=$("$ROCM_VENV/bin/rocm-sdk" path --root)
ARCH=${ARCH:-gfx1036}
LEVELS=${LEVELS:-O1 O2}
TFEL=${TFEL:-$P/install/tfel-mmm-gpu}
MGIS=${MGIS:-$P/install/mgis}
W=$P/scratch/reproducers/hip-finite-strain-3d-hang

# environment of scripts/build-hip-amd.sh: TFEL of the prototype, headers
# of ROCm before the old ones of /usr/include/hip
export PATH=$TFEL/bin:$ROCM/bin:/usr/bin:/bin
export LD_LIBRARY_PATH=$TFEL/lib
export HIP_PLATFORM=amd HIP_PATH=$ROCM ROCM_PATH=$ROCM
export HIPCC_COMPILE_FLAGS_APPEND="-isystem $ROCM/include"
# writes lost after an idle time of the GPU (reproducers/hip-idle-write-loss)
export AMD_SERIALIZE_KERNEL=3 AMD_SERIALIZE_COPY=3

mkdir -p "$W"
hipcc --offload-arch="$ARCH" -O2 -std=c++20 "$R/integrate.cpp" \
  -I"$MGIS/include" -L"$MGIS/lib" -lMFrontGenericInterface \
  -Wl,-rpath,"$MGIS/lib" -o "$W/integrate"

configuration=$TFEL/share/tfel/mfront/configuration-files/config-hip-hipcc.json
for level in $LEVELS; do
  for example in "ex6 SaintVenantKirchhoffElasticity" \
                 "ex4 IsotropicLinearHardeningPlasticity"; do
    read -r directory behaviour <<< "$example"
    d=$W/$directory-$level
    mkdir -p "$d"
    # as mfem_mgis_add_behaviours_library of mfem-mgis
    (cd "$d" && HIP_COMPILER="$ROCM/bin/hipcc" HIP_PLATFORM=amd \
       HIPFLAGS="-fPIC -$level -std=c++20 --offload-arch=$ARCH" \
       mfront --obuild --interface=generic-parallel \
       --configuration-file="$configuration" \
       "$P/mfem-mgis-examples/$directory/$behaviour.mfront" > build.log 2>&1) ||
      { tail "$d/build.log"; exit 1; }
    for hypothesis in PlaneStrain Tridimensional; do
      printf '%-3s %-35s %-15s ' "$level" "$behaviour" "$hypothesis"
      if out=$(timeout -s KILL 30 "$W/integrate" \
                 "$d/src/libGenericParallelBehaviour-hip.so" "$behaviour" 1 \
                 "$hypothesis" 2>&1); then
        echo "$out" | tail -1
      elif [ $? -eq 137 ]; then
        echo "blocked (killed after 30 s)"
      else
        echo "failed: $(echo "$out" | tail -1)"
      fi
    done
  done
done
